:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --accent: #0f3460;
  --text: #eaeaea;
  --text-muted: #a0a0b0;
  --cell-size: 20px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background: var(--bg);
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 24px;
  max-width: 480px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

.header {
  text-align: center;
  margin-bottom: 24px;
}

.header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--primary);
  letter-spacing: 1px;
}

.subtitle {
  color: var(--text-muted);
  font-size: 0.95rem;
  margin-top: 4px;
}

.game-area {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.score-board {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--accent);
  padding: 10px 16px;
  border-radius: 8px;
  font-weight: 600;
}

.score-label {
  color: var(--text-muted);
  text-transform: uppercase;
  font-size: 0.85rem;
  letter-spacing: 1px;
}

#score {
  font-size: 1.25rem;
  color: var(--primary);
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  background: #0b0f1a;
  border-radius: 8px;
  overflow: hidden;
  border: 2px solid var(--accent);
}

#gameCanvas {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(11, 15, 26, 0.92);
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 20px;
  transition: opacity 0.2s ease;
}

.overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

.overlay-content {
  max-width: 320px;
}

.overlay-content h2 {
  font-size: 1.4rem;
  color: var(--primary);
  margin-bottom: 12px;
}

.overlay-content p {
  color: var(--text);
  margin-bottom: 16px;
  font-size: 0.95rem;
}

.hint {
  color: var(--text-muted) !important;
  font-size: 0.85rem !important;
  font-style: italic;
}

.controls {
  display: flex;
  gap: 12px;
}

.btn {
  flex: 1;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 16px;
  border: 2px solid var(--accent);
  border-radius: 8px;
  background: var(--accent);
  color: var(--text);
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.1s ease;
}

.btn:hover {
  background: #1a4a7a;
  border-color: #1a4a7a;
}

.btn:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
  background: var(--primary);
  border-color: var(--primary);
}

.btn.primary {
  background: var(--primary);
  border-color: var(--primary);
}

.btn.primary:hover {
  background: #ff5a75;
  border-color: #ff5a75;
}

.btn.primary:active {
  background: #c73550;
  border-color: #c73550;
}

.how-to-play {
  margin-top: 24px;
  padding-top: 16px;
  border-top: 1px solid var(--accent);
}

.how-to-play h2 {
  font-size: 1.1rem;
  color: var(--text-muted);
  margin-bottom: 8px;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.how-to-play ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.how-to-play li {
  color: var(--text-muted);
  font-size: 0.9rem;
}

.how-to-play strong {
  color: var(--text);
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  .header h1 {
    font-size: 1.5rem;
  }
  .controls {
    flex-direction: column;
  }
  .overlay-content h2 {
    font-size: 1.2rem;
  }
  .overlay-content p {
    font-size: 0.85rem;
  }
}

(function () {
  'use strict';

  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlayTitle');
  const overlayMessage = document.getElementById('overlayMessage');
  const overlayHint = document.getElementById('overlayHint');
  const overlayButton = document.getElementById('overlayButton');
  const pauseBtn = document.getElementById('pauseBtn');
  const restartBtn = document.getElementById('restartBtn');

  const GRID_SIZE = 20;
  const CELL = canvas.width / GRID_SIZE;
  const TICK_MS = 120;

  const COLORS = {
    bg: '#0b0f1a',
    snake: '#e94560',
    snakeHead: '#ff6b81',
    food: '#f5c542',
    grid: '#16213e'
  };

  let snake, direction, nextDirection, food, score, gameState, tickTimer;

  function initGame() {
    snake = [{ x: 10, y: 10 }];
    direction = { x: 1, y: 0 };
    nextDirection = { x: 1, y: 0 };
    score = 0;
    gameState = 'paused';
    scoreEl.textContent = '0';
    placeFood();
    clearInterval(tickTimer);
    tickTimer = null;
    draw();
    showOverlay('How to Play', 'Use the arrow keys to move the snake. Eat the food to grow and increase your score. Avoid running into the walls or yourself!', 'Press any arrow key to start', 'Start Game');
    updatePauseButton();
  }

  function placeFood() {
    let pos;
    do {
      pos = {
        x: Math.floor(Math.random() * GRID_SIZE),
        y: Math.floor(Math.random() * GRID_SIZE)
      };
    } while (snake.some(s => s.x === pos.x && s.y === pos.y));
    food = pos;
  }

  function draw() {
    ctx.fillStyle = COLORS.bg;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.strokeStyle = COLORS.grid;
    ctx.lineWidth = 1;
    for (let i = 1; i < GRID_SIZE; i++) {
      ctx.beginPath();
      ctx.moveTo(i * CELL, 0);
      ctx.lineTo(i * CELL, canvas.height);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, i * CELL);
      ctx.lineTo(canvas.width, i * CELL);
      ctx.stroke();
    }

    ctx.fillStyle = COLORS.food;
    ctx.fillRect(food.x * CELL + 2, food.y * CELL + 2, CELL - 4, CELL - 4);

    for (let i = 0; i < snake.length; i++) {
      const seg = snake[i];
      ctx.fillStyle = i === 0 ? COLORS.snakeHead : COLORS.snake;
      ctx.fillRect(seg.x * CELL + 1, seg.y * CELL + 1, CELL - 2, CELL - 2);
    }
  }

  function showOverlay(title, message, hint, buttonText) {
    overlayTitle.textContent = title;
    overlayMessage.textContent = message;
    overlayHint.textContent = hint;
    overlayButton.textContent = buttonText;
    overlay.classList.remove('hidden');
  }

  function hideOverlay() {
    overlay.classList.add('hidden');
  }

  function updatePauseButton() {
    if (gameState === 'running') {
      pauseBtn.textContent = 'Pause';
      pauseBtn.setAttribute('aria-label', 'Pause game');
    } else if (gameState === 'paused') {
      pauseBtn.textContent = 'Resume';
      pauseBtn.setAttribute('aria-label', 'Resume game');
    } else {
      pauseBtn.textContent = 'Pause';
      pauseBtn.setAttribute('aria-label', 'Pause game');
    }
  }

  function startGame() {
    if (gameState === 'gameover') {
      initGame();
      return;
    }
    if (gameState === 'paused') {
      gameState = 'running';
      hideOverlay();
      updatePauseButton();
      clearInterval(tickTimer);
      tickTimer = setInterval(tick, TICK_MS);
    }
  }

  function pauseGame() {
    if (gameState === 'running') {
      gameState = 'paused';
      clearInterval(tickTimer);
      tickTimer = null;
      showOverlay('Paused', 'The game is paused.', 'Press Resume or any arrow key to continue', 'Resume');
      updatePauseButton();
    } else if (gameState === 'paused') {
      startGame();
    }
  }

  function restartGame() {
    initGame();
  }

  function gameOver() {
    gameState = 'gameover';
    clearInterval(tickTimer);
    tickTimer = null;
    showOverlay('Game Over', 'Your score: ' + score, 'Press Restart or the button below to play again', 'Play Again');
    updatePauseButton();
  }

  function tick() {
    if (gameState !== 'running') return;

    direction = nextDirection;
    const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

    if (head.x < 0 || head.x >= GRID_SIZE || head.y < 0 || head.y >= GRID_SIZE) {
      gameOver();
      return;
    }

    if (snake.some((s, i) => i < snake.length - 1 && s.x === head.x && s.y === head.y)) {
      gameOver();
      return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score += 10;
      scoreEl.textContent = String(score);
      placeFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function handleKey(e) {
    const key = e.key;
    if (key === 'ArrowUp' || key === 'ArrowDown' || key === 'ArrowLeft' || key === 'ArrowRight') {
      e.preventDefault();
      if (gameState === 'gameover') return;
      if (gameState === 'paused') {
        startGame();
      }
      if (key === 'ArrowUp' && direction.y !== 1) nextDirection = { x: 0, y: -1 };
      else if (key === 'ArrowDown' && direction.y !== -1) nextDirection = { x: 0, y: 1 };
      else if (key === 'ArrowLeft' && direction.x !== 1) nextDirection = { x: -1, y: 0 };
      else if (key === 'ArrowRight' && direction.x !== -1) nextDirection = { x: 1, y: 0 };
    }
  }

  window.addEventListener('keydown', handleKey);
  pauseBtn.addEventListener('click', pauseGame);
  restartBtn.addEventListener('click', restartGame);
  overlayButton.addEventListener('click', function () {
    if (gameState === 'gameover') {
      restartGame();
    } else {
      startGame();
    }
  });

  initGame();
})();
